<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { http } from "@/utils/http";
import { message } from "@/utils/message";
const rows = ref<any[]>([]), total = ref(0), loading = ref(false), page = ref(1);
const suppliers = ref<any[]>([]), products = ref<any[]>([]), dialog = ref(false), saving = ref(false);
const form = reactive<any>({ supplierId: undefined, orderDate: new Date().toISOString().slice(0,10), expectedDate: "", paymentMethod: "", remark: "", lines: [] });
const label = (p:any) => `${p.code ?? ""} ${p.name ?? ""}`;
const tagType = (status:number) => (["info","primary","warning","success","danger"][status] ?? "info") as any;
async function load(){ loading.value=true; try { const r:any=await http.request("get","/purchase-order",{params:{page:page.value,pageSize:20}}); if(r.code===0){rows.value=r.data.list??[];total.value=r.data.total??0}else message(r.message,{type:"error"}); } catch(e:any){message(e?.message||"加载失败",{type:"error"})} finally{loading.value=false} }
async function options(){ try { const [s,p]:any[]=await Promise.all([http.request("get","/supplier/options"),http.request("get","/product/options")]); suppliers.value=s.data??[];products.value=p.data??[]; } catch(e:any){message("供应商或产品选项加载失败",{type:"error"})} }
function create(){Object.assign(form,{supplierId:undefined,orderDate:new Date().toISOString().slice(0,10),expectedDate:"",paymentMethod:"",remark:"",lines:[{productId:undefined,qty:1,price:0,deliveryDate:null}]});dialog.value=true}
function add(){form.lines.push({productId:undefined,qty:1,price:0,deliveryDate:null})}
async function save(){if(!form.supplierId||!form.lines.length||form.lines.some((x:any)=>!x.productId||Number(x.qty)<=0||Number(x.price)<0)){message("请填写有效供应商和采购明细",{type:"warning"});return} saving.value=true;try{const r:any=await http.request("post","/purchase-order",{data:{id:0,supplierId:form.supplierId,orderDate:form.orderDate,expectedDate:form.expectedDate||null,paymentMethod:form.paymentMethod||null,remark:form.remark||null,lines:form.lines.map((x:any)=>({id:null,productId:x.productId,qty:Number(x.qty),price:Number(x.price),deliveryDate:x.deliveryDate||null}))}});if(r.code===0){message("采购订单已创建",{type:"success"});dialog.value=false;load()}else message(r.message,{type:"error"})}catch(e:any){message(e?.message||"创建失败",{type:"error"})}finally{saving.value=false}}
async function action(row:any,act:string){try{const r:any=await http.request("post",`/purchase-order/${row.id}/${act}`);if(r.code===0){message(r.message||"操作成功",{type:"success"});load()}else message(r.message,{type:"error"})}catch(e:any){message(e?.message||"操作失败",{type:"error"})}}
onMounted(()=>{options();load()});
</script>
<template><div><el-card shadow="never"><div class="toolbar"><strong>采购订单</strong><el-button type="primary" @click="create">新建采购订单</el-button></div><el-table v-loading="loading" :data="rows" border stripe><el-table-column prop="code" label="订单编号" width="180"/><el-table-column prop="name" label="供应商" min-width="150"/><el-table-column prop="orderDate" label="订单日期" width="120"><template #default="{row}">{{String(row.orderDate||"").slice(0,10)}}</template></el-table-column><el-table-column prop="expectedDate" label="预计到货" width="120"><template #default="{row}">{{row.expectedDate?String(row.expectedDate).slice(0,10):"-"}}</template></el-table-column><el-table-column prop="totalQty" label="数量" width="100"/><el-table-column prop="totalAmount" label="金额" width="130"/><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="tagType(row.orderStatus)">{{["草稿","已确认","部分收货","已完成","已取消"][row.orderStatus]??"未知"}}</el-tag></template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template #default="{row}"><el-button v-if="row.orderStatus===0" link type="primary" @click="action(row,'confirm')">确认</el-button><el-button v-if="row.orderStatus===0||row.orderStatus===1" link type="danger" @click="action(row,'cancel')">取消</el-button><el-button v-if="row.orderStatus===1||row.orderStatus===2" link type="success" @click="$router.push({path:'/purchase/receipt',query:{orderId:row.id}})">收货</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/></div></el-card>
<el-dialog v-model="dialog" title="新建采购订单" width="900px"><el-form label-width="95px"><el-row :gutter="12"><el-col :span="12"><el-form-item label="供应商" required><el-select v-model="form.supplierId" filterable style="width:100%"><el-option v-for="x in suppliers" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="订单日期"><el-date-picker v-model="form.orderDate" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="预计到货"><el-date-picker v-model="form.expectedDate" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="付款方式"><el-input v-model="form.paymentMethod"/></el-form-item></el-col></el-row><el-table :data="form.lines" border size="small"><el-table-column label="产品" min-width="250"><template #default="{row}"><el-select v-model="row.productId" filterable style="width:100%"><el-option v-for="p in products" :key="p.id" :label="label(p)" :value="p.id"/></el-select></template></el-table-column><el-table-column label="数量" width="150"><template #default="{row}"><el-input-number v-model="row.qty" :min="0.001" :precision="3"/></template></el-table-column><el-table-column label="单价" width="150"><template #default="{row}"><el-input-number v-model="row.price" :min="0" :precision="2"/></template></el-table-column><el-table-column width="70"><template #default="{ $index }"><el-button link type="danger" @click="form.lines.splice($index,1)">删除</el-button></template></el-table-column></el-table><el-button style="margin-top:12px" @click="add">添加明细</el-button><el-form-item label="备注" style="margin-top:12px"><el-input v-model="form.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存草稿</el-button></template></el-dialog></div></template>
<style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.pager{display:flex;justify-content:flex-end;margin-top:16px}</style>
